import {safeMediaURL,isSiteOverride} from './media-rules.js';
import {focalPosition} from './photo-settings.js';
import {editorStyles} from './visual-editor.js';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
export async function mediaInventory(api,config){
 const [slots,media,guests]=await Promise.all([fetch('/assets/photo-slots.json').then(r=>{if(!r.ok)throw Error('Photo placements could not load.');return r.json();}),all('elan_media'),all('elan_guests')]);
 async function all(table){let rows=[],offset=0;while(true){const data=await api('admin-list',{table,offset});rows.push(...data.rows);offset+=50;if(offset>=data.total)return rows;}}
 const assets=new Map(),placements=new Map();function add(url,title,alt,placement){if(!safeMediaURL(url,config.supabaseUrl))return;let item=assets.get(url);if(!item){item={url,title:title||url.split('/').pop().replace(/[-_]/g,' ').replace(/\.[^.]+$/,''),alt,placements:[]};assets.set(url,item);}if(placement&&!item.placements.some(p=>p.key===placement.key))item.placements.push(placement);}
 for(const slot of slots){const occurrence=(placements.get(slot.page)||0)+1;placements.set(slot.page,occurrence);const override=media.find(r=>r.published&&r.credit==='site-slot:'+slot.key)||media.find(r=>r.published&&r.credit==='site-image:'+slot.src);add(override?.image_url||slot.src,override?.alt_text||slot.alt,override?.alt_text||slot.alt,{key:slot.key,label:slot.page.replace('.html','').replaceAll('-',' ').replace(/^index$/,'Home')+' · Photo '+occurrence});}
 for(const row of media){if(isSiteOverride(row)){add(row.image_url,row.title,row.alt_text,null);continue;}const key='gallery-'+row.id,override=media.find(r=>r.published&&r.credit==='site-slot:'+key);add(override?.image_url||row.image_url,row.title,override?.alt_text||row.alt_text,{key,label:'Gallery · '+row.category+(row.published?'':' · Draft'),row});if(override)add(row.image_url,row.title,row.alt_text,null);}
 for(const row of guests){for(const part of ['portrait','directory']){const key='guest-'+row.slug+'-'+part,override=media.find(r=>r.published&&r.credit==='site-slot:'+key);add(override?.image_url||row.image_url,row.name,override?.alt_text||row.name,{key,label:'Guests · '+row.name+' · '+part});}}
 return [...assets.values()];
}
export async function chooseMedia({api,config}){const rows=await mediaInventory(api,config);return new Promise(resolve=>{
 const dialog=el('dialog',undefined,'media-picker');dialog.setAttribute('aria-label','Choose an existing photo');const title=el('h2','Choose from your photos'),close=el('button','Cancel'),search=el('input'),label=el('label','Search photos'),grid=el('div',undefined,'media-library-grid');search.type='search';label.append(search);dialog.append(title,close,label,grid);document.body.append(dialog);
 let chosen=null;function render(){grid.replaceChildren();for(const row of rows.filter(r=>(r.title+' '+r.placements.map(p=>p.label).join(' ')).toLowerCase().includes(search.value.toLowerCase()))){const b=el('button',undefined,'media-choice'),img=el('img');img.src=row.url;img.alt='';img.loading='lazy';b.append(img,el('span',row.title||'Photo'));b.onclick=()=>{chosen=row;dialog.close();};grid.append(b);}if(!grid.children.length)grid.textContent='No photos match your search.';}
 close.onclick=()=>dialog.close();search.oninput=render;dialog.addEventListener('close',()=>{dialog.remove();resolve(chosen);},{once:true});render();dialog.showModal();search.focus();
 });}
export async function openMediaLibrary({api,sb,config,host,editor,status,isCurrent}){
 editorStyles();editor.replaceChildren();const [rows,result]=await Promise.all([mediaInventory(api,config),sb.from('elan_photo_settings').select('*')]);if(result.error)throw result.error;if(!isCurrent())return;let settings=new Map(result.data.map(r=>[r.key,r])),dirty=false,busy=false;
 const leave=e=>{if(busy||(dirty&&!confirm('Discard unsaved photo settings?'))){e.preventDefault();return;}document.removeEventListener('elan:admin-leave',leave);window.removeEventListener('beforeunload',before);};const before=e=>{if(dirty){e.preventDefault();e.returnValue='';}};document.addEventListener('elan:admin-leave',leave);window.addEventListener('beforeunload',before);
 host.innerHTML='<section class="app-card"><p class="app-badge">YOUR PHOTO LIBRARY</p><h2>One place for your photos.</h2><p>See where each photo is used, then choose a placement to adjust its crop. In Edit website, choose “Use an existing photo” to reuse one without uploading it again.</p><label>Find a photo or page<input type="search" id="media-search"></label><p id="media-count" role="status"></p><div class="media-library-grid"></div></section>';
 const grid=host.querySelector('.media-library-grid'),search=host.querySelector('input');
 function render(){grid.replaceChildren();const matches=rows.filter(r=>(r.title+' '+r.placements.map(p=>p.label).join(' ')).toLowerCase().includes(search.value.toLowerCase()));host.querySelector('#media-count').textContent=matches.length+' photos';for(const row of matches){const card=el('article',undefined,'media-library-card'),img=el('img');img.src=row.url;img.alt=row.alt;img.loading='lazy';card.append(img,el('h3',row.title||'Photo'));const uses=el('details'),summary=el('summary',row.placements.length?row.placements.length+' current placement(s)':'Available to reuse');uses.append(summary);for(const p of row.placements)uses.append(el('p',p.label));card.append(uses);if(row.placements.length){const b=el('button','Adjust photo display');b.onclick=()=>edit(row);card.append(b);}grid.append(card);}}
 function edit(row){if(busy||(dirty&&!confirm('Discard unsaved photo settings?')))return;dirty=false;editor.innerHTML='<section class="app-card photo-display-editor"><h2>Keep the important part in view.</h2><p>Choose a placement and move the focus point. The full photo is retained.</p><form><label>Placement<select name="placement"></select></label><div class="focal-previews"><figure><img alt="Wide crop preview"><figcaption>Wide screen crop</figcaption></figure><figure><img alt="Narrow crop preview"><figcaption>Narrow screen crop</figcaption></figure></div><label>Horizontal focus <input name="x" type="range" min="0" max="100"></label><label>Vertical focus <input name="y" type="range" min="0" max="100"></label><output></output><div class="gallery-photo-flags"><label><input type="checkbox" name="featured"> Feature near the start of the gallery</label><label><input type="checkbox" name="cover"> Use as the cover of this gallery group</label></div><button type="submit">Save photo display</button><p role="status"></p></form></section>';
 const form=editor.querySelector('form');for(const p of row.placements){const o=el('option',p.label);o.value=p.key;form.placement.append(o);}for(const img of form.querySelectorAll('img'))img.src=row.url;
 function preview(){const position=focalPosition({focal_x:form.x.value,focal_y:form.y.value});form.querySelectorAll('img').forEach(img=>img.style.objectPosition=position);form.querySelector('output').textContent='Focus: '+position;}
 function select(){const p=row.placements.find(p=>p.key===form.placement.value),v=settings.get(p.key)||{};form.x.value=v.focal_x??50;form.y.value=v.focal_y??50;form.featured.checked=!!v.featured;form.cover.checked=!!v.is_cover;form.querySelector('.gallery-photo-flags').hidden=!p.row;preview();dirty=false;}
 let previous=form.placement.value;form.placement.onchange=()=>{if(dirty&&!confirm('Discard unsaved photo settings?')){form.placement.value=previous;return;}previous=form.placement.value;select();};form.oninput=e=>{if(e.target===form.placement)return;dirty=true;preview();};select();
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;form.inert=true;try{const p=row.placements.find(p=>p.key===form.placement.value),value={key:p.key,focal_x:Number(form.x.value),focal_y:Number(form.y.value),featured:!!p.row&&form.featured.checked,is_cover:!!p.row&&form.cover.checked,updated_at:new Date().toISOString()},updates=[value];
 if(value.is_cover)for(const asset of rows)for(const other of asset.placements)if(other.row&&other.key!==p.key&&other.row.category===p.row.category&&settings.get(other.key)?.is_cover)updates.push({...settings.get(other.key),is_cover:false,updated_at:value.updated_at});
 const r=await sb.from('elan_photo_settings').upsert(updates).select();if(r.error)throw r.error;if(r.data.length!==updates.length)throw Error('The save was not confirmed. Please retry.');for(const v of r.data)settings.set(v.key,v);dirty=false;form.querySelector('[role=status]').textContent='Saved. This photo display is now live.';status('Photo settings saved.');}catch(err){form.querySelector('[role=status]').textContent=err.message;status(err.message,true);}finally{busy=false;form.inert=false;}};
 editor.scrollIntoView({block:'start',behavior:'auto'});
 }
 search.oninput=render;render();status('');
}
